import { createHash } from 'node:crypto'
import { execFileSync } from 'node:child_process'
import { readFileSync, readdirSync, writeFileSync } from 'node:fs'
import { parseFramingPlan } from '../../src/lib/import/framing-plan/parse'
import { compact, recoverRows } from '../../src/lib/import/runs'

const parserPath = 'src/lib/import/framing-plan/parse.ts'
const sha = (value: string | Buffer) => createHash('sha256').update(value).digest('hex')
if (process.argv[2] === 'before') {
  const committed = execFileSync('git', ['show', `HEAD:${parserPath}`])
  const working = readFileSync(parserPath)
  if (committed.toString().replace(/\r\n/g, '\n') !== working.toString().replace(/\r\n/g, '\n')) throw Error('Parser differs from HEAD')
}
const directory = 'tests/fixtures/section-import/textitems'
const files = readdirSync(directory).filter(file => file.endsWith('.json')).sort()
if (files.length !== 36) throw Error(`Unexpected page count: ${files.length}`)
const pages = files.map(file => {
  const bytes = readFileSync(`${directory}/${file}`)
  const fixture = JSON.parse(bytes.toString())
  const output = parseFramingPlan({ ...fixture.page, items: fixture.items })
  return {
    file, fixture_sha256: sha(bytes), output,
    title_tokens: recoverRows(fixture.items).flatMap(row => row.segments.map(segment => compact(segment.text))).filter(text => /伏図|柱芯線図|リスト/.test(text)),
  }
})
const result = {
  head: execFileSync('git', ['rev-parse', 'HEAD'], {encoding:'utf8'}).trim(),
  parser_sha256: sha(readFileSync(parserPath)), pages,
}
writeFileSync(`tmp/phase42-step1/${process.argv[2]}.json`, JSON.stringify(result, null, 2) + '\n')
console.log(JSON.stringify({pages:pages.length, grids:pages.reduce((sum, p)=>sum+p.output.grids.length,0), blocks:pages.reduce((sum,p)=>sum+p.output.blocks.length,0), outliers:pages.flatMap(p=>p.output.grids.filter(g=>g.scalePtPerMm<0.005||g.scalePtPerMm>0.1).map(g=>({file:p.file,...g}))), karatsu:pages.find(p=>p.file==='karatsu-fukuzu-p1.json')}))
